update sc_plans set title=$q$He shared his umbrella with a stray… 🐶☔$q$, title_ko=$q$오래전 비 오는 날, 소년이 학교 앞에서 젖은 강아지에게 하트 그린 노란 우산을 씌워 주고 자기는 비를 맞는다. 세월이 흘러 늙어 눈이 흐려진 그 개가 우산을 물고 학교로 가고, 까치가 앞에서 길을 이끈다. 학교 앞에서 기다리던 사람은 이 학교 선생님이 된 그 소년. 이번엔 그가 늙은 개에게 우산을 씌운다.$q$, hook=$q$첫 컷: 소년은 왜 자기는 비를 맞으며 강아지에게 우산을 씌울까?$q$, emotion='animal', korea=$q$시골 초등학교 교문·누렁이·가을비$q$, outline=$q$[{"scene": "오래전 가을비, 시골 학교 교문. 소년이 젖은 강아지에게 하트 노란 우산을 씌우고 자기는 비를 맞는다", "cap": "He shared his umbrella with a stray."}, {"scene": "세월 뒤, 늙어 눈이 흐린 개가 그 우산을 물고 걷고, 까치가 코앞에서 길을 이끈다", "cap": "Years later, he still brought it."}, {"scene": "교문 처마 밑, 선생님이 된 소년이 길 쪽을 보고 놀라 미소", "cap": ""}, {"scene": "선생님이 쪼그려 앉아 늙은 개에게 우산을 씌우고 자기는 비를 맞는다(1컷과 같은 구도)", "cap": "Now it's his turn."}]$q$::jsonb, spec=spec || $q${"bible": {"boy": "BOY (years ago): a Korean boy about eight, round face, short black hair, navy hoodie, red backpack.", "teacher": "TEACHER (now): the same boy grown into a young man in his late twenties: same round face and short black hair, grey cardigan over a white shirt, a teacher's lanyard with a plain blank card.", "puppy": "PUPPY: a small soaked golden-yellow Korean village puppy (nureongi) with floppy ears.", "olddog": "OLD DOG: the same golden-yellow nureongi now old and big, a grey-white muzzle, slightly cloudy eyes, a faded red collar.", "umbrella": "UMBRELLA: a child's bright yellow umbrella with one small white heart hand-painted on one panel.", "place": "PLACE: the gate of a small countryside elementary school: two plain stone gateposts, a short covered entrance with a tiled roof, a muddy village road with rice paddies behind, autumn rain."}, "details": [{"prop": "하얀 하트를 그린 노란 우산", "where": [1, 2, 4], "meaning": "그때 그 우산 — 세월을 잇는 물건"}, {"prop": "늙은 개의 흐린 눈·회색 주둥이", "where": [2, 4], "meaning": "앞이 잘 안 보여 까치가 길잡이가 된다"}, {"prop": "1컷과 4컷의 같은 구도(우산 아래 개, 비 맞는 등)", "where": [1, 4], "meaning": "역할이 바뀐 보답"}], "format": "kindness-returns (세월 뒤 갚기)", "hook_type": "why-question-first-frame", "music": "music_i-believe-2", "pinned": "Who was YOUR first best friend? 🐶 Tell Kachi 💛", "description": "Years ago, a little boy gave a stray puppy his umbrella.\nYears later, the old dog still came… and Kachi showed him the way.\n\nIn Korea, the magpie is the bird that brings good news 🐦\n\n#Dog #Kindness #Korea #Wholesome #DogLove #shorts", "tags": ["dog", "puppy", "old dog", "umbrella", "rain", "kindness", "Korea", "magpie", "miniature animation", "Kachi", "From Korea With Love"], "notes": "얼굴 일관성: 3·4컷 선생님은 du1 을 ref. 한 컷 최대 2인물: 4컷엔 까치 없음(까치 역할은 2컷 길잡이). 목걸이 카드는 빈 카드(글자 없음).", "reuse": [], "followup_of": null, "est_usd": 1.5, "cuts": 4, "p0_scores": {"surprise": 4, "emotion": 5, "natural": 4, "kachi": 4}, "production": {"gen_img": "scripts/side/gen_next/M261101-dog-umbrella-img.json", "gen_vid": "scripts/side/gen_next/M261101-dog-umbrella-vid.json", "render_id": "E261101-dog-umbrella"}, "shots": []}$q$::jsonb, status='approved', updated_at=now(), feedback=feedback || jsonb_build_array($q${"by": "claude", "type": "note", "text": "이전안(반전 없음) P0 미달이라 새로 씀: 소년이 강아지에게 우산 → 세월 뒤 늙은 개가 우산을 물고 까치 길잡이 → 선생님이 된 소년이 이번엔 개에게 우산. PLAN-FIRST 촬영표 완성(4컷·엔딩 포함 약 22초·예상 실비 $1.5: 그림 4·영상 4). P0 점수 놀라움 4·감정 5·자연스러움 4·까치 역할 4 → 승인. 생성 작업 파일: scripts/side/gen_next/M261101-dog-umbrella-img.json / -vid.json (제작 때 scripts/side/gen/ 로 옮겨 실행)."}$q$::jsonb || jsonb_build_object('at',now())) where id='P261030-dog-umbrella'